require("dotenv").config();

const bcrypt = require("bcryptjs");
const { PrismaClient } = require("@prisma/client");
const { getAdminCredentials } = require("./seedConfig");

const prisma = new PrismaClient();

// Add manual records using the Food/Room fields in schema.prisma; IDs are generated by Prisma.
const foodEntries = [];
const roomEntries = [];

async function main() {
  const { adminEmail, adminPassword } = getAdminCredentials();
  const hashedPassword = await bcrypt.hash(adminPassword, 12);

  await prisma.user.upsert({
    where: { email: adminEmail },
    update: { name: "1Hotel Administrator", password: hashedPassword, role: "ADMIN" },
    create: {
      name: "1Hotel Administrator",
      email: adminEmail,
      password: hashedPassword,
      role: "ADMIN",
    },
  });

  for (const food of foodEntries) {
    await prisma.food.create({ data: food });
  }

  for (const room of roomEntries) {
    await prisma.room.create({ data: room });
  }

  console.log(`Admin account ready: ${adminEmail}`);
}

main()
  .catch((error) => {
    console.error(error);
    process.exitCode = 1;
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
